'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs/promises');
const os=require('node:os');
const path=require('node:path');
const {randomUUID}=require('node:crypto');
const {OfflineNotes,ProtectedStore}=require('../reference/offline-notes-client.cjs');
(async()=>{
 const input=JSON.parse(require('node:fs').readFileSync(0,'utf8'));
 const directory=await fs.mkdtemp(path.join(os.tmpdir(),'field81-'));
 const identity=randomUUID();
 let drop=false,submissions=0;
 const transport=async(p,method,body,auth)=>{
  if(p==='/sync/operations'&&method==='POST')submissions++;
  const r=await fetch(input.url+p,{method,headers:{Authorization:'Bearer '+auth.token,'Content-Type':'application/json',...(auth.operation?{'Operation-ID':auth.operation}:{}),...(auth.epoch?{'X-FreeFSM-Session-Epoch':auth.epoch}:{})},body:body===undefined?undefined:JSON.stringify(body)});
  const data=await r.json();
  if(r.status>=400)console.log(`field transport status=${r.status} code=${data.error?.code||'unknown'}`);
  if(drop&&p==='/sync/operations'){drop=false;throw Error('lost_response');}
  return {...data,status:r.status};
 };
 let client=new OfflineNotes(new ProtectedStore(directory,identity),transport);
 const fixture=async action=>assert.equal((await fetch(input.url+'/__fixture/'+action,{method:'POST'})).status,204);
 try {
  await client.initialize();await client.authenticate(input.token);await client.synchronize();
  let view=await client.view();const job=Object.keys(view.cache)[0];
  const selected=()=>view.cache[job].status_definitions.find(s=>s.id===input.target);
  const stageStatus=()=>client.stageStatus(job,input.target,view.cache[job].status_revision,selected().meaning_revision,[]);
  const first=await stageStatus();
  await fixture('rename');
  drop=true;await assert.rejects(client.submitBatch([first]),/lost_response/);
  client=new OfflineNotes(new ProtectedStore(directory,identity),transport);
  assert.equal((await client.reconcile(first)).state,'accepted');
  await client.synchronize(true);view=await client.view();
  assert.equal(view.cache[job].status.id,input.target);
  assert.equal(selected().name,'Cosmetic target');
  const attribution=structuredClone(view.cache[job].status_attribution);
  assert.ok(attribution?.actor_id&&attribution?.accepted_at,'recorded Status attribution is required');
  const same=await stageStatus();assert.equal((await client.submitBatch([same]))[0].state,'accepted');
  await client.synchronize(true);view=await client.view();assert.deepEqual(view.cache[job].status_attribution,attribution);
  const other=view.cache[job].status_definitions.find(s=>s.category==='job:new');
  const stale=await client.stageStatus(job,other.id,view.cache[job].status_revision,other.meaning_revision,[]);
  const away=await client.stageStatus(job,other.id,view.cache[job].status_revision,other.meaning_revision,[]);
  assert.equal((await client.submitBatch([away]))[0].state,'accepted');
  await client.synchronize(true);view=await client.view();
  const back=await stageStatus();assert.equal((await client.submitBatch([back]))[0].state,'accepted');
  assert.equal((await client.submitBatch([stale]))[0].receipt.code,'status_reselection_required');
  await client.synchronize(true);view=await client.view();
  const semantic=await stageStatus();
  const dependentTask=view.cache[job].subtasks[0];
  const child=await client.stageSubtask(job,dependentTask.id,true,dependentTask.completion_revision,[semantic]);
  await fixture('category');
  const blocked=await client.submitBatch([semantic,child]);
  assert.equal(blocked[0].receipt.code,'status_reselection_required');assert.equal(blocked[1].receipt.code,'failed_dependency');
  await client.synchronize(true);view=await client.view();
  const repaired=await client.repairStatus(semantic,input.target,view.cache[job].status_revision,selected().meaning_revision,[]);
  const repairedChild=await client.repairSubtask(child,true,view.cache[job].subtasks[0].completion_revision,[repaired]);
  assert.deepEqual((await client.view()).pending[child].batch.depends_on,[semantic]);
  assert.notEqual(repaired,semantic);assert.notEqual(repairedChild,child);
  assert.deepEqual((await client.submitBatch([repaired,repairedChild])).map(r=>r.state),['accepted','accepted']);
  await client.synchronize(true);view=await client.view();
  const replacement=await stageStatus();await fixture('replace');
  assert.equal((await client.submitBatch([replacement]))[0].receipt.code,'status_reselection_required');
  await client.synchronize(true);view=await client.view();
  const sameLabel=view.cache[job].status_definitions.find(s=>s.name==='Cosmetic target');
  assert.ok(sameLabel&&sameLabel.id!==input.target,'replacement must preserve label while changing identity');
  const task=view.cache[job].subtasks[0];
  const complete=await client.stageSubtask(job,task.id,true,task.completion_revision,[]);
  assert.equal((await client.submitBatch([complete]))[0].state,'accepted');
  await client.synchronize(true);view=await client.view();
  const recorded=structuredClone(view.cache[job].subtasks[0]);
  assert.ok(recorded.completion_actor&&recorded.completion_at,'recorded completion attribution is required');
  const noop=await client.stageSubtask(job,task.id,true,recorded.completion_revision,[]);
  assert.equal((await client.submitBatch([noop]))[0].state,'accepted');
  await client.synchronize(true);view=await client.view();assert.deepEqual(view.cache[job].subtasks[0],recorded);
  const beforeRestore=submissions;
  await fixture('restore');await assert.rejects(client.synchronize(true),/locked_review/);
  await assert.rejects(client.view(),/locked_review/);
  const fresh=await (await fetch(input.url+'/__fixture/token',{method:'POST'})).json();
  await client.authenticate(fresh.token);await client.synchronize();view=await client.view();
  assert.equal(view.pending[complete].state,'restore_uncertain');
  await client.reconcile(complete);
  await assert.rejects(client.repairSubtask(complete,true,recorded.completion_revision,[]),/restore_reconciliation_required/);
  await client.acknowledgeUncertain(complete);
  assert.equal(submissions,beforeRestore,'restore recovery automatically replayed work');
  const reviewedRestore=await client.repairSubtask(complete,true,recorded.completion_revision,[]);
  assert.notEqual(reviewedRestore,complete);assert.equal((await client.submitBatch([reviewedRestore]))[0].state,'accepted');
  const removed=await client.stageSubtask(job,task.id,false,recorded.completion_revision,[]);
  await fixture('remove');assert.equal((await client.submitBatch([removed]))[0].receipt.code,'not_found');
  await client.synchronize();view=await client.view();assert.equal(view.cache[job].subtasks.length,0);
  assert.equal(view.cache[job].subtask_history.at(-1).action,'remove');
  const bytes=await fs.readFile(path.join(directory,'cache'));assert.equal(bytes.includes(Buffer.from(input.token)),false);assert.equal(bytes.includes(Buffer.from('Original task')),false);
  console.log('PASS encrypted Status/Subtask restart, semantic repair, deltas, removal and no-op attribution');
 } finally {await client.logout();await fs.rm(directory,{recursive:true,force:true});}
})().catch(e=>{console.error(e);process.exitCode=1;});
